def eprint(s=""):
    print(s, file=sys.stderr)


def usage_options() -> str:
    return f"Usage: {prog()} [OPTIONS]"


def cli_error(msg: str, usage: Optional[str] = None):
    eprint(f"error: {msg}")
    eprint()
    if usage:
        eprint(usage)
        eprint()
    eprint("For more information, try '--help'.")
    sys.exit(2)


def cli_missing(canon: str):
    cli_error(f"a value is required for '{canon}' but none was supplied")


def cli_unexpected_arg(arg: str):
    cli_error(f"unexpected argument '{arg}' found", usage_options())


def cli_unexpected_value(flag: str, val: str):
    cli_error(f"unexpected value '{val}' for '{flag}' found; no more were expected", f"Usage: {prog()} {flag}")


def cli_invalid_value(opt: str, val: str, reason: str):
    cli_error(f"invalid value '{val}' for '{opt}': {reason}")


@dataclass
class CliOptions:
    no_update: bool = False
    no_confirm: bool = False
    no_detach: bool = False
    dry_run: bool = False
    bases: List[str] = field(default_factory=list)
    protected: List[str] = field(default_factory=list)
    delete: List[str] = field(default_factory=list)
    update_interval: Optional[int] = None


def validate_uint_value(val: str):
    if val == "" or not all(ch.isdigit() for ch in val):
        cli_invalid_value("--update-interval <UPDATE_INTERVAL>", val, "invalid digit found in string")
    return int(val)


def parse_argv(argv: List[str]) -> CliOptions:
    opts = CliOptions()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            if i + 1 < len(argv):
                cli_unexpected_arg(argv[i+1])
            cli_unexpected_arg(a)
        if a == "--help":
            print_long_help(); sys.exit(0)
        if a == "-h":
            print_short_help(); sys.exit(0)
