def eprint(s=""):
    print(s, file=sys.stderr)


def usage_options() -> str:
    return f"Usage: {prog()} [OPTIONS]"


def cli_error(msg: str, usage: Optional[str] = None):
    eprint(f"error: {msg}")
    eprint()
    if usage:
        eprint(usage)
        eprint()
    eprint("For more information, try '--help'.")
    sys.exit(2)


def cli_missing(canon: str):
    cli_error(f"a value is required for '{canon}' but none was supplied")


def cli_unexpected_arg(arg: str):
    cli_error(f"unexpected argument '{arg}' found", usage_options())


def cli_unexpected_value(flag: str, val: str):
    cli_error(f"unexpected value '{val}' for '{flag}' found; no more were expected", f"Usage: {prog()} {flag}")


def cli_invalid_value(opt: str, val: str, reason: str):
    cli_error(f"invalid value '{val}' for '{opt}': {reason}")


@dataclass
class CliOptions:
    no_update: bool = False
    no_confirm: bool = False
    no_detach: bool = False
    dry_run: bool = False
    bases: List[str] = field(default_factory=list)
    protected: List[str] = field(default_factory=list)
    delete: List[str] = field(default_factory=list)
    update_interval: Optional[int] = None


def validate_uint_value(val: str):
    if val == "" or not all(ch.isdigit() for ch in val):
        cli_invalid_value("--update-interval <UPDATE_INTERVAL>", val, "invalid digit found in string")
    return int(val)


def parse_argv(argv: List[str]) -> CliOptions:
    opts = CliOptions()
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--":
            if i + 1 < len(argv):
                cli_unexpected_arg(argv[i+1])
            cli_unexpected_arg(a)
        if a == "--help":
            print_long_help(); sys.exit(0)
        if a == "-h":
            print_short_help(); sys.exit(0)
        if a == "--version" or a == "-V" or (a.startswith("-V") and not a.startswith("--")):
            print(VERSION); sys.exit(0)
        # Long flags and options
        if a.startswith("--"):
            if "=" in a:
                name, val = a.split("=", 1)
                if name in ("--no-update", "--no-confirm", "--no-detach", "--dry-run"):
                    cli_unexpected_value(name, val)
                if name == "--bases":
                    opts.bases.append(val); i += 1; continue
                if name == "--protected":
                    opts.protected.append(val); i += 1; continue
                if name == "--delete":
                    # validate now for clap-style diagnostics
                    parse_delete_values([val], cli=True)
                    opts.delete.append(val); i += 1; continue
                if name == "--update-interval":
                    opts.update_interval = validate_uint_value(val); i += 1; continue
                cli_unexpected_arg(a)
            if a == "--no-update":
                opts.no_update = True; i += 1; continue
            if a == "--no-confirm":
                opts.no_confirm = True; i += 1; continue
            if a == "--no-detach":
                opts.no_detach = True; i += 1; continue
            if a == "--dry-run":
                opts.dry_run = True; i += 1; continue
            if a in ("--bases", "--protected", "--delete", "--update-interval"):
                canon = {
                    "--bases": "--bases <BASES>",
                    "--protected": "--protected <PROTECTED>",
                    "--delete": "--delete <DELETE>",
                    "--update-interval": "--update-interval <UPDATE_INTERVAL>",
                }[a]
                if i + 1 >= len(argv):
                    cli_missing(canon)
                val = argv[i+1]
                if val.startswith("-"):
                    # clap treats a hyphen-looking unsigned integer value as a new unexpected argument.
                    cli_unexpected_arg(val)
                if a == "--bases":
                    opts.bases.append(val)
                elif a == "--protected":
                    opts.protected.append(val)
                elif a == "--delete":
                    parse_delete_values([val], cli=True)
                    opts.delete.append(val)
                else:
                    opts.update_interval = validate_uint_value(val)
                i += 2; continue
            cli_unexpected_arg(a)
        # Short options with optional attached values
        if a.startswith("-") and a != "-":
            if a.startswith("-b"):
                if len(a) > 2:
                    val = a[2:]
                    opts.bases.append(val); i += 1; continue
                if i + 1 >= len(argv):
                    cli_missing("--bases <BASES>")
                val = argv[i+1]
                if val.startswith("-"):
                    cli_unexpected_arg(val)
                opts.bases.append(val); i += 2; continue
            if a.startswith("-p"):
                if len(a) > 2:
                    val = a[2:]
                    opts.protected.append(val); i += 1; continue
                if i + 1 >= len(argv):
                    cli_missing("--protected <PROTECTED>")
                val = argv[i+1]
                if val.startswith("-"):
                    cli_unexpected_arg(val)
                opts.protected.append(val); i += 2; continue
            if a.startswith("-d"):
                if len(a) > 2:
                    val = a[2:]
                    parse_delete_values([val], cli=True)
                    opts.delete.append(val); i += 1; continue
                if i + 1 >= len(argv):
                    cli_missing("--delete <DELETE>")
                val = argv[i+1]
                if val.startswith("-"):
                    cli_unexpected_arg(val)
                parse_delete_values([val], cli=True)
                opts.delete.append(val); i += 2; continue
            # very small amount of short flag grouping for help/version
            if "h" in a[1:]:
                print_short_help(); sys.exit(0)
            cli_unexpected_arg(a)
        else:
            cli_unexpected_arg(a)
    return opts


@dataclass
class DeleteSettings:
    merged_local: bool = False
    stray: bool = False
    local: bool = False
    merged_remote: List[str] = field(default_factory=list)
    remote: List[str] = field(default_factory=list)
    diverged: List[str] = field(default_factory=list)


class DeleteParseError(Exception):
    def __init__(self, token: str, msg: str):
        super().__init__(msg)
        self.token = token
        self.msg = msg


def parse_one_delete(token: str) -> Tuple[str, Optional[str]]:
    if token in ("merged-local", "stray", "local"):
        return (token, None)
    for pfx in ("merged", "merged-remote", "remote", "diverged"):
        marker = pfx + ":"
        if token.startswith(marker):
            scope = token[len(marker):]
            if scope == "":
                raise DeleteParseError(token, "Scope parse error for delete range while parsing scope: Scope is empty")
            return (pfx, scope)
    raise DeleteParseError(token, f"Invalid delete range format `{token}`")


def parse_delete_values(values: List[str], cli: bool=False) -> DeleteSettings:
    st = DeleteSettings()
    for raw in values:
        for token in raw.split(','):
            try:
                kind, scope = parse_one_delete(token)
            except DeleteParseError as e:
                if cli:
                    cli_invalid_value("--delete <DELETE>", e.token, e.msg)
                raise
            if kind == "merged-local":
                st.merged_local = True
            elif kind == "stray":
                st.stray = True
            elif kind == "local":
                st.local = True
            elif kind == "merged":
                st.merged_local = True
                st.merged_remote.append(scope or "")
            elif kind == "merged-remote":
                st.merged_remote.append(scope or "")
            elif kind == "remote":
                st.remote.append(scope or "")
            elif kind == "diverged":
                st.diverged.append(scope or "")
    return st


def split_comma_values(vals: List[str]) -> List[str]:
    out: List[str] = []
    for v in vals:
        for x in v.split(','):
            if x != "":
                out.append(x)
    return out


def git_capture(args: List[str], check: bool=False) -> subprocess.CompletedProcess:
    cp = subprocess.run(["git"] + args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and cp.returncode != 0:
        raise RuntimeError(cp.stderr.strip() or cp.stdout.strip())
    return cp


def git_config_get(key: str) -> Optional[str]:
    cp = git_capture(["config", "--get", key])
    if cp.returncode == 0:
        return cp.stdout.rstrip('\n')
    return None


def git_config_bool(key: str) -> Optional[bool]:
    cp = git_capture(["config", "--bool", "--get", key])
    if cp.returncode == 0:
        val = cp.stdout.strip().lower()
        if val == "true":
            return True
        if val == "false":
            return False
    return None


def ensure_repo_and_remotes() -> List[str]:
    cp = git_capture(["rev-parse", "--git-dir"])
    if cp.returncode != 0:
        eprint("Error: could not find repository at '.'; class=Repository (6); code=NotFound (-3)")
        sys.exit(1)
    cp = git_capture(["remote"])
    remotes = [l for l in cp.stdout.splitlines() if l]
    if not remotes:
        eprint("Error: git-trim requires at least one remote")
        sys.exit(1)
    return remotes


@dataclass
class LocalBranch:
    name: str
    full: str
    oid: str
    upstream_full: str = ""
    upstream_short: str = ""
    is_head: bool = False


@dataclass
class RemoteBranch:
    remote: str
    branch: str
    display: str
    full: str
    oid: str


def load_local_branches() -> Dict[str, LocalBranch]:
    fmt = "%(refname)%00%(refname:short)%00%(objectname)%00%(upstream)%00%(upstream:short)%00%(HEAD)"
    cp = git_capture(["for-each-ref", f"--format={fmt}", "refs/heads"])
    res: Dict[str, LocalBranch] = {}
    for line in cp.stdout.splitlines():
        parts = line.split('\x00')
        if len(parts) < 6:
            continue
        full, short, oid, upfull, upshort, head = parts[:6]
        res[short] = LocalBranch(short, full, oid, upfull, upshort, head == "*")
    return res


def parse_remote_full(full: str) -> Optional[Tuple[str, str]]:
    p = "refs/remotes/"
    if not full.startswith(p):
        return None
    rest = full[len(p):]
    if "/" not in rest:
        return None
    remote, branch = rest.split('/', 1)
    if branch == "HEAD":
        return None
    return remote, branch


def load_remote_branches() -> Dict[str, RemoteBranch]:
    fmt = "%(refname)%00%(objectname)"
    cp = git_capture(["for-each-ref", f"--format={fmt}", "refs/remotes"])
    res: Dict[str, RemoteBranch] = {}
    for line in cp.stdout.splitlines():
        parts = line.split('\x00')
        if len(parts) < 2:
            continue
        full, oid = parts[:2]
        pr = parse_remote_full(full)
        if not pr:
            continue
        remote, branch = pr
        display = f"{remote}/{branch}"
        res[full] = RemoteBranch(remote, branch, display, full, oid)
    return res


def remote_head_refs(remotes: List[str]) -> Set[str]:
    s: Set[str] = set()
    for r in remotes:
        cp = git_capture(["symbolic-ref", "-q", f"refs/remotes/{r}/HEAD"])
        if cp.returncode == 0:
            ref = cp.stdout.strip()
            if ref:
                s.add(ref)
    return s


def scope_matches(scopes: List[str], remote: str) -> bool:
    return any(sc == "*" or sc == remote for sc in scopes)


def first_protected(patterns: List[str], name: str) -> Optional[str]:
    for pat in patterns:
        if fnmatch.fnmatchcase(name, pat):
            return pat
    return None


_ancestor_cache: Dict[Tuple[str, str], bool] = {}

def is_ancestor(a: str, b: str) -> bool:
    if not a or not b:
        return False
    if a == b:
        return True
    key = (a, b)
    if key in _ancestor_cache:
        return _ancestor_cache[key]
    cp = subprocess.run(["git", "merge-base", "--is-ancestor", a, b], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    ok = (cp.returncode == 0)
    _ancestor_cache[key] = ok
    return ok


def short_commit_and_subject(ref: str) -> str:
    cp = git_capture(["log", "-1", "--format=%h %s", ref])
    if cp.returncode == 0:
        return cp.stdout.strip()
    cp = git_capture(["rev-parse", "--short", ref])
    return cp.stdout.strip() if cp.returncode == 0 else ref


@dataclass
class RemainItem:
    name: str
    ann: str = ""


@dataclass
class LocalDelete:
    name: str
    section: str  # merged or stray
    list_suffix: str = ""
    oid: str = ""
    is_head: bool = False


@dataclass
class RemoteDelete:
    remote: str
    branch: str
    section: str  # merged or diverged
    list_suffix: str = ""


def analyze(remotes: List[str], base_values: List[str], protected_patterns: List[str], dels: DeleteSettings):
    locals_d = load_local_branches()
    remotes_d = load_remote_branches()

    # Determine bases. Empty explicit value means fall back to default.
    explicit_bases = split_comma_values(base_values)
    base_local_names: Set[str] = set()
    base_remote_refs: Set[str] = set()
    if explicit_bases:
        for b in explicit_bases:
            lb = locals_d.get(b)
            if lb and lb.upstream_full and lb.upstream_full in remotes_d:
                base_local_names.add(lb.name)
                base_remote_refs.add(lb.upstream_full)
    else:
        heads = remote_head_refs(remotes)
        for lb in locals_d.values():
            if lb.upstream_full and lb.upstream_full in heads and lb.upstream_full in remotes_d:
                base_local_names.add(lb.name)
                base_remote_refs.add(lb.upstream_full)

    base_oids = [remotes_d[r].oid for r in base_remote_refs if r in remotes_d]

    def merged_any(oid: str) -> bool:
        return any(is_ancestor(oid, b) for b in base_oids)

    # Map upstream remote refs to local branches (all configured upstreams that currently exist).
    upstream_to_locals: Dict[str, List[LocalBranch]] = {}
    for lb in locals_d.values():
        if lb.upstream_full and lb.upstream_full in remotes_d:
            upstream_to_locals.setdefault(lb.upstream_full, []).append(lb)
    for v in upstream_to_locals.values():
        v.sort(key=lambda x: x.name)

    tracking_scan_active = dels.merged_local or bool(dels.merged_remote) or dels.stray or bool(dels.diverged)

    local_remain: List[RemainItem] = []
    remote_remain: List[RemainItem] = []
    local_deletes: List[LocalDelete] = []
    remote_deletes: List[RemoteDelete] = []
    used_skip: Set[int] = set()

    # Local branches.
    for name in sorted(locals_d.keys()):
        lb = locals_d[name]
        prot = first_protected(protected_patterns, name)
        has_upstream_config = bool(lb.upstream_full)
        upstream_exists = has_upstream_config and lb.upstream_full in remotes_d
        up_rb = remotes_d.get(lb.upstream_full) if upstream_exists else None
        remote_name = up_rb.remote if up_rb else None
        local_merged = merged_any(lb.oid)
        upstream_merged = merged_any(up_rb.oid) if up_rb else False
        is_base = name in base_local_names

        def add_remain(annotation: str = ""):
            local_remain.append(RemainItem(name, annotation))

        if not has_upstream_config:
            if dels.local:
                if local_merged:
                    if prot:
                        add_remain(f" [merged, but: protected by a pattern `{prot}`]")
                    elif lb.is_head and not CURRENT_DETACH_ENABLED:
                        add_remain(" [merged, but: HEAD]")
                    else:
                        local_deletes.append(LocalDelete(name, "merged", " (non-tracking)", lb.oid, lb.is_head))
                else:
                    add_remain("")
            else:
                used_skip.add(2)
                add_remain(" *2")
            continue

        # Tracking-style branch (even when upstream ref is gone).
        if not tracking_scan_active:
            used_skip.add(1)
            add_remain(" *1")
            continue

        if is_base:
            if local_merged:
                add_remain(" [base]")
            else:
                add_remain(" [stray, but: base]")
            continue

        if upstream_exists:
            # A merged local whose upstream is not merged is treated as a diverged pair.
            if local_merged and not upstream_merged:
                up_display_full = f"refs/remotes/{up_rb.remote}/{up_rb.branch}"
                div_active = scope_matches(dels.diverged, up_rb.remote)
                pair_prot = prot or first_protected(protected_patterns, up_rb.display)
                if div_active:
                    if pair_prot:
                        add_remain(f" [diverged with {up_display_full}, but: protected by a pattern `{pair_prot}`]")
                    elif lb.is_head and not CURRENT_DETACH_ENABLED:
                        add_remain(f" [diverged with {up_display_full}, but: HEAD]")
                    else:
                        local_deletes.append(LocalDelete(name, "merged", "", lb.oid, lb.is_head))
                else:
                    add_remain(f" [diverged with {up_display_full}, but: delete range `diverged:{up_rb.remote}` was not given]")
                continue

            if local_merged:
                if dels.merged_local:
                    if prot:
                        add_remain(f" [merged, but: protected by a pattern `{prot}`]")
                    elif lb.is_head and not CURRENT_DETACH_ENABLED:
                        add_remain(" [merged, but: HEAD]")
                    else:
                        local_deletes.append(LocalDelete(name, "merged", "", lb.oid, lb.is_head))
                else:
                    add_remain(" [merged, but: delete range `merged-local` was not given]")
            else:
                # Not merged. If its upstream is already merged/base, or vanished, it is stray.
                if upstream_merged:
                    if dels.stray:
                        if prot:
                            add_remain(f" [stray, but: protected by a pattern `{prot}`]")
                        elif lb.is_head and not CURRENT_DETACH_ENABLED:
                            add_remain(" [stray, but: HEAD]")
                        else:
                            local_deletes.append(LocalDelete(name, "stray", "", lb.oid, lb.is_head))
                    else:
                        add_remain(" [stray, but: delete range `stray` was not given]")
                else:
                    add_remain("")
            continue

        # Upstream configured but gone.
        if local_merged:
            if dels.merged_local:
                if prot:
                    add_remain(f" [merged, but: protected by a pattern `{prot}`]")
                elif lb.is_head and not CURRENT_DETACH_ENABLED:
                    add_remain(" [merged, but: HEAD]")
                else:
                    local_deletes.append(LocalDelete(name, "merged", "", lb.oid, lb.is_head))
            else:
                add_remain(" [merged, but: delete range `merged-local` was not given]")
        else:
            if dels.stray:
                if prot:
                    add_remain(f" [stray, but: protected by a pattern `{prot}`]")
                elif lb.is_head and not CURRENT_DETACH_ENABLED:
                    add_remain(" [stray, but: HEAD]")
                else:
                    local_deletes.append(LocalDelete(name, "stray", "", lb.oid, lb.is_head))
            else:
                add_remain(" [stray, but: delete range `stray` was not given]")

    # Remote references.
    remote_items = list(remotes_d.values())
    remote_items.sort(key=lambda rb: (rb.remote, rb.branch), reverse=False)
    # Observed reports list later remote names first, but branch names ascending within a remote.
    remote_items.sort(key=lambda rb: rb.branch)
    remote_items.sort(key=lambda rb: rb.remote, reverse=True)

    scheduled_remote_keys: Set[Tuple[str, str, str]] = set()

    for rb in remote_items:
        prot = first_protected(protected_patterns, rb.display)
        is_base = rb.full in base_remote_refs
        remote_merged = merged_any(rb.oid)
        assoc = upstream_to_locals.get(rb.full, [])
        is_upstream = bool(assoc)

        def add_r(annotation: str = ""):
            remote_remain.append(RemainItem(rb.display, annotation))

        if is_upstream:
            # Choose the first associated local branch for pair diagnostics.
            lb = assoc[0]
            local_merged = merged_any(lb.oid)
            if not tracking_scan_active:
                used_skip.add(1)
                add_r(" *1")
                continue
            if is_base:
                add_r(" [base]")
                continue
            if local_merged and not remote_merged:
                div_active = scope_matches(dels.diverged, rb.remote)
                local_prot = first_protected(protected_patterns, lb.name)
                pair_prot = local_prot or prot
                local_ref = f"refs/heads/{lb.name}"
                if div_active:
                    if pair_prot:
                        add_r(f" [diverged with {local_ref}, but: protected by a pattern `{pair_prot}`]")
                    elif lb.is_head and not CURRENT_DETACH_ENABLED:
                        add_r(f" [diverged with {local_ref}, but: HEAD]")
                    else:
                        key = (rb.remote, rb.branch, "diverged")
                        if key not in scheduled_remote_keys:
                            remote_deletes.append(RemoteDelete(rb.remote, rb.branch, "diverged", ""))
                            scheduled_remote_keys.add(key)
                else:
                    add_r(f" [diverged with {local_ref}, but: delete range `diverged:{rb.remote}` was not given]")
                continue
            if remote_merged:
                if scope_matches(dels.merged_remote, rb.remote):
                    if prot:
                        add_r(f" [merged, but: protected by a pattern `{prot}`]")
                    else:
                        key = (rb.remote, rb.branch, "merged")
                        if key not in scheduled_remote_keys:
                            remote_deletes.append(RemoteDelete(rb.remote, rb.branch, "merged", ""))
                            scheduled_remote_keys.add(key)
                else:
                    add_r(f" [merged, but: delete range `merged-remote:{rb.remote}` was not given]")
            else:
                add_r("")
        else:
            # Remote ref that is not the upstream of a local tracking branch.
            if scope_matches(dels.remote, rb.remote):
                if remote_merged:
                    if prot:
                        add_r(f" [merged non-upstream, but: protected by a pattern `{prot}`]")
                    else:
                        key = (rb.remote, rb.branch, "merged-non")
                        if key not in scheduled_remote_keys:
                            remote_deletes.append(RemoteDelete(rb.remote, rb.branch, "merged", " (non-upstream)"))
                            scheduled_remote_keys.add(key)
                else:
                    add_r("")
            else:
                # If this is a base ref with tracking scan, show it as base; otherwise it is skipped as non-upstream.
                if is_base and tracking_scan_active:
                    add_r(" [base]")
                else:
                    used_skip.add(3)
                    add_r(" *3")

    local_deletes.sort(key=lambda x: x.name)
    remote_deletes.sort(key=lambda x: (x.remote, x.branch))
    # Report order for remote names follows the same reverse-name convention.
    remote_deletes.sort(key=lambda x: x.branch)
    remote_deletes.sort(key=lambda x: x.remote, reverse=True)

    return local_remain, remote_remain, local_deletes, remote_deletes, used_skip


def print_report(local_remain: List[RemainItem], remote_remain: List[RemainItem], local_deletes: List[LocalDelete], remote_deletes: List[RemoteDelete], used_skip: Set[int]):
    print("Branches that will remain:")
    print("  local branches:")
    for it in local_remain:
        print(f"    {it.name}{it.ann}")
    print("  remote references:")
    for it in remote_remain:
        print(f"    {it.name}{it.ann}")
    if used_skip:
        print("  Some branches are skipped. Consider following to scan them:")
        if 1 in used_skip:
            print("    *1: Add `--delete 'merged:*'` flag.")
        if 2 in used_skip:
            print("    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag.")
        if 3 in used_skip:
            # If all skipped non-upstream refs are from one remote, the original suggests that remote.
            # The generic wildcard is a safe default; callers mainly compare the common origin case.
            rems = sorted({it.name.split('/',1)[0] for it in remote_remain if it.ann == " *3"})
            if len(rems) == 1:
                print(f"    *3: Make it upstream of a tracking branch or add `--delete 'remote:{rems[0]}'` flag.")
            else:
                print("    *3: Make it upstream of a tracking branch or add `--delete 'remote:*'` flag.")
    print()

    merged_locals = [d for d in local_deletes if d.section == "merged"]
    stray_locals = [d for d in local_deletes if d.section == "stray"]
    merged_remotes = [d for d in remote_deletes if d.section == "merged"]
    diverged_remotes = [d for d in remote_deletes if d.section == "diverged"]

    if merged_locals:
        print("Delete merged local branches:")
        for d in merged_locals:
            print(f"  - {d.name}{d.list_suffix}")
    if merged_remotes:
        print("Delete merged remote refs:")
        for d in merged_remotes:
            print(f"  - {d.remote}, refs/heads/{d.branch}{d.list_suffix}")
    if diverged_remotes:
        print("Delete diverged remote refs:")
        for d in diverged_remotes:
            print(f"  - {d.remote}, refs/heads/{d.branch}{d.list_suffix}")
    if stray_locals:
        print("Delete stray local branches:")
        for d in stray_locals:
            print(f"  - {d.name}{d.list_suffix}")


def group_remote_deletes(remote_deletes: List[RemoteDelete]) -> Dict[str, List[RemoteDelete]]:
    grouped: Dict[str, List[RemoteDelete]] = {}
    for d in remote_deletes:
        grouped.setdefault(d.remote, []).append(d)
    return grouped


def perform_remote_deletes(remote_deletes: List[RemoteDelete], dry_run: bool) -> int:
    grouped = group_remote_deletes(remote_deletes)
    # Use report order (reverse remote name, branch ascending) for push groups.
    for remote in sorted(grouped.keys(), reverse=True):
        ds = sorted(grouped[remote], key=lambda x: x.branch)
        args = ["push"]
        if dry_run:
            args.append("--dry-run")
        args.append(remote)
        args.extend([f":refs/heads/{d.branch}" for d in ds])
        sys.stdout.flush(); sys.stderr.flush()
        cp = subprocess.run(["git"] + args)
        if cp.returncode != 0:
            return cp.returncode
    return 0


def perform_local_deletes(local_deletes: List[LocalDelete], dry_run: bool, detach_enabled: bool) -> int:
    for d in sorted(local_deletes, key=lambda x: x.name):
        if d.is_head and detach_enabled:
            if dry_run:
                info = short_commit_and_subject(f"refs/heads/{d.name}")
                print(f"Note: switching to 'refs/heads/{d.name}' (dry run)")
                print("You are in 'detached HED' state... blah blah...")
                print(f"HEAD is now at {info} (dry run)")
            else:
                sys.stdout.flush(); sys.stderr.flush()
                cp = subprocess.run(["git", "checkout", "--detach", f"refs/heads/{d.name}"])
                if cp.returncode != 0:
                    return cp.returncode
        if dry_run:
            print(f"Delete branch {d.name} (dry run).")
        else:
            sys.stdout.flush(); sys.stderr.flush()
            cp = subprocess.run(["git", "branch", "-D", d.name])
            if cp.returncode != 0:
                return cp.returncode
    return 0


def ask_confirm_or_error() -> bool:
    if not sys.stdin.isatty():
        eprint("Error: IO error: not a terminal")
        eprint()
        eprint("Caused by:")
        eprint("    not a terminal")
        sys.exit(1)
    try:
        ans = input("Confirm? [y/N] ")
    except EOFError:
        ans = ""
    ok = ans.strip().lower() in ("y", "yes")
    if not ok:
        print("Cancelled")
    return ok


# The analyzer references this global to decide whether HEAD can be scheduled.
CURRENT_DETACH_ENABLED = True


def main():
    global CURRENT_DETACH_ENABLED
    cli = parse_argv(sys.argv[1:])
    remotes = ensure_repo_and_remotes()

    # Config and CLI precedence.
    update_enabled = True
    cv = git_config_bool("trim.update")
    if cv is not None:
        update_enabled = cv
    if cli.no_update:
        update_enabled = False

    confirm_enabled = True
    cv = git_config_bool("trim.confirm")
    if cv is not None:
        confirm_enabled = cv
    if cli.no_confirm:
        confirm_enabled = False

    detach_enabled = True
    cv = git_config_bool("trim.detach")
    if cv is not None:
        detach_enabled = cv
    if cli.no_detach:
        detach_enabled = False
    CURRENT_DETACH_ENABLED = detach_enabled

    # Option values: command-line replaces config; config replaces default.
    base_values: List[str]
    if cli.bases:
        base_values = cli.bases
    else:
        conf = git_config_get("trim.bases")
        base_values = [conf] if conf is not None else []

    protected_values: List[str]
    if cli.protected:
        protected_values = cli.protected
    else:
        conf = git_config_get("trim.protected")
        protected_values = [conf] if conf is not None else []
    protected_patterns = split_comma_values(protected_values)

    if cli.delete:
        delete_values = cli.delete
        try:
            dels = parse_delete_values(delete_values, cli=False)
        except DeleteParseError as e:
            eprint(f"Error: {e.msg}")
            sys.exit(1)
    else:
        conf = git_config_get("trim.delete")
        if conf is not None:
            try:
                dels = parse_delete_values([conf], cli=False)
            except DeleteParseError as e:
                eprint(f"Error: {e.msg}")
                sys.exit(1)
        else:
            dels = parse_delete_values(["merged:origin"], cli=False)

    # Parse config updateInterval enough to report invalid values similarly at runtime.
    if cli.update_interval is None:
        conf_ui = git_config_get("trim.updateInterval")
        if conf_ui is not None and (conf_ui == "" or not all(ch.isdigit() for ch in conf_ui)):
            eprint("Error: invalid digit found in string")
            sys.exit(1)

    if update_enabled:
        if cli.dry_run:
            print()
        else:
            for r in remotes:
                print(f"Fetching {r}")
                sys.stdout.flush()
                cp = subprocess.run(["git", "fetch", "--prune", r])
                if cp.returncode != 0:
                    sys.exit(1)
            print()

    local_remain, remote_remain, local_deletes, remote_deletes, used_skip = analyze(remotes, base_values, protected_patterns, dels)
    print_report(local_remain, remote_remain, local_deletes, remote_deletes, used_skip)

    if not local_deletes and not remote_deletes:
        return 0

    if not cli.dry_run and confirm_enabled:
        if not ask_confirm_or_error():
            return 0

    # Remote pushes first, then local branch changes, matching the visible side effects.
    rc = perform_remote_deletes(remote_deletes, cli.dry_run)
    if rc != 0:
        return 1
    rc = perform_local_deletes(local_deletes, cli.dry_run, detach_enabled)
    if rc != 0:
        return 1
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            sys.exit(1)
