for args in "--no-update --dry-run --no-confirm" "--no-update --no-confirm" "--no-update --no-confirm --no-detach"; do dir=/tmp/gittrim-test-head-$(echo "$args"|tr ' -' '__'|tr -cd A-Za-z0-9_); make_repo "$dir" >/tmp/setupout 2>/tmp/setuperr; cd "$dir/work"; echo "===== $args ====="; set +e; /workspace/executable $args > /tmp/out 2>/tmp/err; code=$?; set -e; echo "[exit $code] stdout:"; cat -vet /tmp/out; echo stderr; cat -vet /tmp/err; git status --short --branch | cat -vet; cd /tmp; done

